# Shared deterministic composition contract; no historical scene data.
from pathlib import Path
import json, html, subprocess
P=Path(__file__).resolve().parent; C=P/'compositions/frames'; C.mkdir(parents=True,exist_ok=True)
beats=json.loads((P/'submission-beats.json').read_text()); meta=json.loads((P/'submission-audio-meta.json').read_text()); E={}
css='''@font-face{font-family:"DM Sans";src:url("assets/dm-sans-variable.woff2") format("woff2");font-weight:100 1000}*{box-sizing:border-box}html,body{margin:0;background:#F3F1EA;color:#17231D;font-family:"DM Sans",sans-serif}#pitch{position:relative;width:100%;height:100%;overflow:hidden;background:#F3F1EA}.clip{position:absolute;inset:0;width:100%;height:100%;overflow:hidden}h1,h2,h3,p{margin:0}.green{color:#3E6A50}.rust{color:#B3472E}.muted{color:#626F65}.title{position:absolute;left:96px;top:132px;font-size:83px;font-weight:720;line-height:1.01;letter-spacing:-.045em;max-width:1700px}.eyebrow{font-size:22px;letter-spacing:.08em;text-transform:uppercase}.foot{position:absolute;left:96px;right:96px;top:871px;font-size:22px;line-height:1.3;color:#626F65}.capture{position:absolute;overflow:hidden;background:#10161b;border:2px solid #D5D9CD;border-radius:10px}.capture img,.capture video{display:block;width:100%;height:100%;object-fit:cover}.screen{position:absolute;left:96px;right:96px;top:322px;height:505px;border-radius:10px;border:2px solid #D5D9CD;overflow:hidden;background:#10161b}.screen .world{width:100%;height:1080px;position:absolute;left:0;top:0;transform-origin:50% 50%}.world img{width:100%;height:1080px;object-fit:fill}.annotation{position:absolute;left:96px;right:96px;top:657px;height:190px;background:#F3F1EA;border-top:2px solid #17231D;padding:18px 0}.trace-label{font-size:19px;letter-spacing:.08em;color:#626F65}.trace{display:flex;gap:32px;align-items:center;margin-top:15px}.trace strong{font-size:41px;letter-spacing:-.025em}.trace p{font-size:27px;line-height:1.3}.trace code,.code{font:inherit;overflow-wrap:anywhere}.arrow{flex:0 0 100px;width:100px;height:44px}.arrow path{fill:none;stroke:#3E6A50;stroke-width:3}.n{font-size:145px;font-weight:720;letter-spacing:-.06em;line-height:1}.rail{position:absolute;left:96px;right:96px;top:39px;display:flex;justify-content:space-between;align-items:center;height:53px;border-bottom:2px solid #D5D9CD;font-size:21px}.brand{font-size:30px;font-weight:720;letter-spacing:-.04em}.brand img{width:29px;height:29px;vertical-align:middle;margin-right:10px}.rail-note{font-size:19px;letter-spacing:.025em}.footer{position:absolute;left:96px;right:96px;bottom:20px;display:flex;justify-content:space-between;font-size:18px;color:#626F65}.progress{position:absolute;bottom:0;height:5px;background:#3E6A50;width:100%;transform-origin:left}.caption-line{display:flex;align-items:flex-end;justify-content:center;padding:0 100px 66px;pointer-events:none}.caption-line span{display:block;font-size:29px;line-height:1.25;max-width:1700px;background:#17231D;color:#F3F1EA;padding:10px 20px;border-radius:5px;text-align:center}.pane{position:absolute;border-top:2px solid #D5D9CD}.pill{display:inline-block;padding:8px 16px;border:2px solid #D5D9CD;border-radius:7px;font-size:23px}.receipt{position:absolute;left:96px;right:96px;top:693px;border-top:2px solid #17231D;padding-top:15px;display:flex;align-items:center;justify-content:space-between}.receipt p{font-size:24px;line-height:1.4}.receipt strong{font-size:43px}.smallnote{font-size:21px;line-height:1.3;color:#626F65}.quote{font-size:37px;line-height:1.23;font-weight:520;letter-spacing:-.015em}.line{height:2px;background:#D5D9CD;transform-origin:left}.tag{font-size:22px;letter-spacing:.04em;text-transform:uppercase}'''
(P/'style.css').write_text(css)
helper='''function enter(sel,t,dx=0){tl.fromTo(sel,{opacity:0,x:dx,y:dx?0:45},{opacity:1,x:0,y:0,duration:.5,ease:"power4.out",stagger:.07},t)}function cam(sel,t,s,x,y){tl.to(sel,{scale:s,x:x,y:y,duration:1.2,ease:"power2.inOut"},t)}function draw(sel,t){document.querySelectorAll(sel).forEach(p=>{let n=p.getTotalLength();tl.fromTo(p,{strokeDasharray:n,strokeDashoffset:n},{strokeDashoffset:0,duration:.65,ease:"power2.out"},t)})}'''
def arrow(id):return f'<svg class="arrow" viewBox="0 0 100 44"><path id="{id}" d="M0 22H95M80 7L95 22L80 37"/></svg>'
def plate(i,name,detail=True):return f'<div class="screen" id="f{i}-screen"><div class="world" data-layout-allow-overflow id="f{i}-world"><img src="capture/{name}{"-detail" if detail else ""}.png" alt="Actual recorded evidence from the completed run"/><video id="f{i}-evidence-video" class="clip" src="capture/{name}.mp4" data-start="0" data-duration="4" data-track-index="0" muted playsinline style="width:100%;height:1080px;object-fit:fill"></video></div></div>'
scenes=[]
def scene(i,name,body,code):
 b=beats[i-1];id=f'f{i}';src=f'compositions/frames/{i:02}-{name}.html'
 content=f'<template><div id="{id}" data-composition-id="{id}" data-duration="{b["duration"]}"><style>#{id}{{position:absolute;inset:0;width:100%;height:100%;overflow:hidden}}@font-face{{font-family:"DM Sans";src:url("assets/dm-sans-variable.woff2") format("woff2");font-weight:100 1000}}</style>{body}</div><script>(function(){{let tl=gsap.timeline({{paused:true}});{helper}{code}window.__timelines["{id}"]=tl;}})();</script></template>'
 (P/src).write_text(content);scenes.append(dict(src=src,**b));return f'<div id="{id}" class="clip" data-composition-id="{id}" data-composition-src="{src}" data-start="{b["start"]}" data-duration="{b["duration"]}" data-width="1920" data-height="1080" data-track-index="{i}" data-track-kind="graphics"></div>'
